sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading) {
        return;
    }

    // Only allow numbers and limit to 10 characters
    var cleanNumber = newValue.replace(/[^0-9]/g, '').substring(0, 10);

    // Update the field with cleaned value
    g_form.setValue('mobile_number', cleanNumber);

    // Validate the mobile number
    var validation = new x_1900237_github_0.MobileNumberValidation().validateMobileNumber(cleanNumber);

    if (!validation.valid) {
        g_form.showFieldMsg('mobile_number', validation.message, 'error');
        g_form.clearValue('mobile_number');
    } else {
        g_form.clearFieldMsg('mobile_number');
    }
}
